package main

import (
	"fmt"
	"sort"
)

var price = map[int]int{1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}

// all groups: each group is a subset of the 5 titles (size 1..5)
var groups [][]int

func init() {
	for mask := 1; mask < 32; mask++ {
		g := []int{}
		for t := 0; t < 5; t++ {
			if mask&(1<<t) != 0 {
				g = append(g, t)
			}
		}
		groups = append(groups, g)
	}
}

func key(c [5]int) int {
	k := 0
	for _, v := range c {
		k = k*1000 + v
	}
	return k
}

func brute(c [5]int) int {
	if c[0]+c[1]+c[2]+c[3]+c[4] == 0 {
		return 0
	}
	best := 1 << 30
	for _, g := range groups {
		ok := true
		for _, t := range g {
			if c[t] == 0 {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		nc := c
		for _, t := range g {
			nc[t]--
		}
		cost := price[len(g)] + brute(nc)
		if cost < best {
			best = cost
		}
	}
	return best
}

func main() {
	cases := []struct {
		desc     string
		basket   []int
		expected int
	}{
		{"Only a single book", []int{1}, 800},
		{"Two of the same book", []int{2, 2}, 1600},
